INSERT INTO public.products (id, name, description, price, created_at, updated_at) VALUES ('e680f731-cfde-427f-9077-62f7e484ec21', '독도 저자극 토너 & 로션 듀오 기획 세트', '울릉도 해양심층수의 풍부한 미네랄로 피부를 순하고 촉촉하게 가꿔주는 저자극 수분 듀오 세트', 32000, now() - interval '34 days', now());
INSERT INTO public.products (id, name, description, price, created_at, updated_at) VALUES ('0c85306c-89fa-4a83-9e16-5540ee3b68aa', '히알루론산 딥 모이스처 수분 크림 100ml 대용량', '8중 복합 히알루론산으로 피부 속 깊이 촘촘하게 수분막을 형성해주는 무향 수분크림', 28000, now() - interval '15 days', now());
INSERT INTO public.products (id, name, description, price, created_at, updated_at) VALUES ('63d4efec-06f6-43d2-93b4-11b26b88c9e3', '시카 릴리프 카밍 에센스 50ml', '고농축 병풀 추출물(CICA)과 마데카소사이드 성분이 붉어지고 예민해진 피부를 빠르게 진정시키는 카밍 에센스', 24000, now() - interval '42 days', now());
