INSERT INTO public.products (id, name, description, price, created_at, updated_at) VALUES ('833d50fc-4c16-42df-8745-72b36f305dd6', '비타민C 시트러스 브라이트닝 잡티 세럼', '순수 비타민C와 나이아신아마이드 배합으로 칙칙한 잡티와 기미를 케어해주는 고농축 미백 세럼', 35000, now() - interval '49 days', now());
