INSERT INTO public.products (id, name, description, price, created_at, updated_at) VALUES ('a9f84554-81bd-4252-89af-f3c91733406a', '이너뷰티 저분자 콜라겐 & 유산균 30포', '하루 한 포로 챙기는 흡수율 높은 300달톤 저분자 피쉬콜라겐과 포스트바이오틱스 복합 이너뷰티', 26900, now() - interval '47 days', now());
INSERT INTO public.products (id, name, description, price, created_at, updated_at) VALUES ('04472697-d7c5-4cbe-bbc1-3cb62d3d4eba', '티트리 트러블 진정 퀵 카밍 패드 80매', '제주산 티트리 추출물을 가득 머금어 트러블 부위를 빠르게 진정시키고 각질을 케어하는 비건 인증 패드', 22000, now() - interval '45 days', now());
INSERT INTO public.products (id, name, description, price, created_at, updated_at) VALUES ('1adcc870-2ca1-4731-a698-2e1ac3451eae', '약산성 리프레싱 약쑥 클렌징 폼 200ml', '강화 약쑥 추출물의 편안함과 조밀한 약산성 거품으로 세안 후에도 당김 없이 노폐물을 세정하는 약산성 폼', 15000, now() - interval '45 days', now());
INSERT INTO public.products (id, name, description, price, created_at, updated_at) VALUES ('ca7292aa-6e29-4772-8481-4ff1ace806a6', '아르간 손상 모발 집중 케어 헤어 에센스 오일 120ml', '손상되고 푸석한 모발에 아르간 오일과 실크 단백질을 공급하여 끈적임 없이 빛나는 윤기를 부여하는 헤어 오일', 18000, now() - interval '48 days', now());
