INSERT INTO public.reviews (id, product_id, source, reviewer_type, review_text, rating, review_date, sentiment, sentiment_score, keywords, issue_type, ai_summary, created_at, review_id) VALUES ('28b9cc72-ba31-420c-98bd-726c4164bc76', 'a9f84554-81bd-4252-89af-f3c91733406a', '네이버 뷰티윈도', '수부지(수분부족형지성) 피부', '수분감은 괜찮은데 가격 대비 양이 조금 적은 것 같아요. 아쉽습니다. 무난무난해서 쓰기 딱이에요.', 3, '2026-05-01', 'neutral', -0.02, ARRAY['가성비아쉬움', '용량적음'], '백탁/밀림', '용량 및 가성비 보통 불만족', '2026-05-01 06:24:30', 'b2bf3b2a-7488-40e8-8081-ebfe58725ae0');
INSERT INTO public.reviews (id, product_id, source, reviewer_type, review_text, rating, review_date, sentiment, sentiment_score, keywords, issue_type, ai_summary, created_at, review_id) VALUES ('89eb8dfb-09cb-471e-a75b-c65351321f4b', '1adcc870-2ca1-4731-a698-2e1ac3451eae', '쿠팡 뷰티스토어', '수부지(수분부족형지성) 피부', '나쁘진 않은데 이 돈 주고 다시 살지는 고민해 볼 것 같습니다. 무난무난해서 쓰기 딱이에요.', 3, '2026-04-30', 'neutral', -0.04, ARRAY['재구매고민', '보통'], '백탁/밀림', '재구매 매력 보통 불만족', '2026-04-30 03:24:30', '7293594e-db89-49e7-9065-fefb18ea23f7');
INSERT INTO public.reviews (id, product_id, source, reviewer_type, review_text, rating, review_date, sentiment, sentiment_score, keywords, issue_type, ai_summary, created_at, review_id) VALUES ('d98982f9-299e-4ba4-89b1-1b74578a27ce', '63d4efec-06f6-43d2-93b4-11b26b88c9e3', '화해 쇼핑', '민감성 피부', '좁쌀 트러블 다 들어갔어요! 순하고 흡수도 빨라서 정착합니다. 피부 결이 진짜 보들보들해져요.', 5, '2026-04-30', 'positive', 0.81, ARRAY['진정', '트러블케어', '대만족'], NULL, '트러블 진정 효과 우수 만족', '2026-04-30 06:24:30', '7c4918f4-da4c-4569-aa1f-23929f91d73c');
INSERT INTO public.reviews (id, product_id, source, reviewer_type, review_text, rating, review_date, sentiment, sentiment_score, keywords, issue_type, ai_summary, created_at, review_id) VALUES ('9bf86368-010a-4427-9198-3960df5eada9', 'ca7292aa-6e29-4772-8481-4ff1ace806a6', '올리브영 온/오프라인', '건성 피부', '향도 은은하고 마무리가 산뜻해요. 끈적임 싫어하시는 분들께 강력 추천합니다. 피부 결이 진짜 보들보들해져요.', 5, '2026-03-27', 'positive', 0.92, ARRAY['무향선호', '산뜻함', '추천'], NULL, '끈적임 없는 마무리 만족 만족', '2026-03-27 04:24:30', 'ac392af7-74fa-44d9-af3f-ec9340f7ad28');
