INSERT INTO public.reviews (id, product_id, source, reviewer_type, review_text, rating, review_date, sentiment, sentiment_score, keywords, issue_type, ai_summary, created_at, review_id) VALUES ('67500382-c12b-4764-93d0-2ee04ca4c723', '116a021c-1268-441d-aa30-ec5c87156e12', '쿠팡 뷰티스토어', '복합성 피부', '자극이 전혀 없어서 팩처럼 화장솜에 듬뿍 적셔 쓰고 있어요. 피부 결이 달라집니다.', 5, '2026-02-20', 'positive', 0.97, ARRAY['스킨팩', '피부결개선', '대만족'], NULL, '스킨팩 활용 및 결 개선 만족', '2026-02-20 07:24:30', 'c0400e7a-7a47-4c89-80a5-7ba4e382641a');
INSERT INTO public.reviews (id, product_id, source, reviewer_type, review_text, rating, review_date, sentiment, sentiment_score, keywords, issue_type, ai_summary, created_at, review_id) VALUES ('4fb56df4-ff65-4232-a403-911de4067084', 'ca7292aa-6e29-4772-8481-4ff1ace806a6', '올리브영 온/오프라인', '건성 피부', '이틀 썼는데 붉은 반점이 온 얼굴에 퍼졌어요. 성분이 순하다는 광고는 다 구라입니다. 다음번엔 굳이 안 살 듯요.', 1, '2026-05-10', 'negative', -0.95, ARRAY['붉은반점', '허위광고', '비추'], '용기불량/파손', '피부 붉은 반점 부작용 불만족', '2026-05-10 02:24:30', '4ccdafa6-5256-49ef-a0f8-1b7ebac4e567');
INSERT INTO public.reviews (id, product_id, source, reviewer_type, review_text, rating, review_date, sentiment, sentiment_score, keywords, issue_type, ai_summary, created_at, review_id) VALUES ('df3b516a-cceb-4d98-a2f1-55012de79b9b', 'e680f731-cfde-427f-9077-62f7e484ec21', '글로우픽 뷰티스토어', '건성 피부', '바르고 나면 약간 막이 씌워진 답답함이 있는데, 시간 지나면 건조해지네요. 무난무난해서 쓰기 딱이에요.', 3, '2026-05-10', 'neutral', 0.14, ARRAY['속건조', '막씌워짐', '보통'], '배송지연/파손', '속건조 개선 아쉬움 불만족', '2026-05-10 13:24:30', '3aa90cf4-7902-437a-b533-010f3192252c');
INSERT INTO public.reviews (id, product_id, source, reviewer_type, review_text, rating, review_date, sentiment, sentiment_score, keywords, issue_type, ai_summary, created_at, review_id) VALUES ('6b1a0b2c-b809-433a-a5ee-1324fd4fdc3d', '116a021c-1268-441d-aa30-ec5c87156e12', '네이버 뷰티윈도', '건성 피부', '향이 지독한 인공 인공향이라 머리가 너무 아파요. 향 민감하신 분들은 사지 마세요. 민감성이신 분들 피하세요ㅠ', 2, '2026-03-13', 'negative', -0.68, ARRAY['인공향지독', '두통유발', '비추'], NULL, '인공향 부적합 불만족', '2026-03-13 16:24:30', '84bac02f-95d6-40c2-bff8-137450acb5fb');
