INSERT INTO public.reviews (id, product_id, source, reviewer_type, review_text, rating, review_date, sentiment, sentiment_score, keywords, issue_type, ai_summary, created_at, review_id) VALUES ('a6a55024-bcc5-49a6-8461-e270ed4bbf52', 'a9f84554-81bd-4252-89af-f3c91733406a', '올리브영 온/오프라인', '복합성 피부', '이너뷰티 제품인데 맛도 상큼하고 먹기 편해서 매일 챙겨 먹고 있어요. 피부 생기가 도네요. 피부 결이 진짜 보들보들해져요.', 5, '2026-03-16', 'positive', 0.74, ARRAY['이너뷰티', '상큼한맛', '생기'], NULL, '복용 편의성 및 효과 우수 만족', '2026-03-16 17:24:30', 'a5237cfd-15ba-48b9-ad63-6818fe9a3d47');
