INSERT INTO public.reviews (id, product_id, source, reviewer_type, review_text, rating, review_date, sentiment, sentiment_score, keywords, issue_type, ai_summary, created_at, review_id) VALUES ('e475c2f9-6bf6-4229-ae6d-94708b1ad1c7', '0c85306c-89fa-4a83-9e16-5540ee3b68aa', '화해 쇼핑', '지성 피부', '촉촉하고 무난한 데일리 수분 템입니다. 흡수력이 살짝 느린 것 빼곤 만족해요. 대용량 개이득~', 4, '2026-04-06', 'positive', 0.92, ARRAY['데일리케어', '흡수력', '무난'], NULL, '데일리 케어 흡수력 무난 만족', '2026-04-06 14:24:30', 'a9055c81-de86-4a17-8f0a-4dd6e81ec8f9');
