INSERT INTO public.reviews (id, product_id, source, reviewer_type, review_text, rating, review_date, sentiment, sentiment_score, keywords, issue_type, ai_summary, created_at, review_id) VALUES ('f1f9f879-d4b3-49f8-88e1-a1a2e43cf89b', 'e680f731-cfde-427f-9077-62f7e484ec21', '쿠팡 뷰티스토어', '지성 피부', '성분이 착해서 그런지 민감성 피부인데 붉어짐 없이 너무 잘 맞아요. 피부 결이 진짜 보들보들해져요.', 5, '2026-04-14', 'positive', 0.72, ARRAY['성분', '순함', '민감성추천'], NULL, '저자극 성분 만족 만족', '2026-04-14 04:24:30', '08a8b7eb-61cc-4291-a9eb-9ea4be72e66f');
