INSERT INTO public.reviews (id, product_id, source, reviewer_type, review_text, rating, review_date, sentiment, sentiment_score, keywords, issue_type, ai_summary, created_at, review_id) VALUES ('a4084d17-f554-4c65-8f07-7eea8955afef', '116a021c-1268-441d-aa30-ec5c87156e12', '네이버 뷰티윈도', '건성 피부', '유통기한이 3달밖에 안 남은 악성 재고가 배송되었습니다. 정말 실망스럽네요. 다음번엔 굳이 안 살 듯요.', 2, '2026-02-22', 'negative', -0.76, ARRAY['유통기한임박', '재고처리', '비추'], '트러블/여드름', '유통기한 임박 배송 불만족', '2026-02-22 08:24:30', 'ea2111a7-e02a-428b-8c8a-8aef01a5245b');
INSERT INTO public.reviews (id, product_id, source, reviewer_type, review_text, rating, review_date, sentiment, sentiment_score, keywords, issue_type, ai_summary, created_at, review_id) VALUES ('e985f99b-e347-40c7-9ea5-41eb78cbb733', '0c85306c-89fa-4a83-9e16-5540ee3b68aa', '네이버 뷰티윈도', '복합성 피부', '향이 지독한 인공 인공향이라 머리가 너무 아파요. 향 민감하신 분들은 사지 마세요. 다음번엔 굳이 안 살 듯요.', 2, '2026-05-14', 'negative', -0.95, ARRAY['인공향지독', '두통유발', '비추'], '유통기한', '인공향 부적합 불만족', '2026-05-14 13:24:30', '212572d8-cf8a-4fe5-85cc-bdb862b7df1e');
INSERT INTO public.reviews (id, product_id, source, reviewer_type, review_text, rating, review_date, sentiment, sentiment_score, keywords, issue_type, ai_summary, created_at, review_id) VALUES ('0b042bb0-5a57-478e-9ed9-e7b4a5137bf3', 'cda7adcd-30e5-4610-8dd6-d1b48a3e018a', '화해 쇼핑', '수부지(수분부족형지성) 피부', '저한테는 안 맞았는지 좁쌀 여드름이 얼굴 전체에 올라왔어요. 돈 아깝네요. 민감성이신 분들 피하세요ㅠ', 2, '2026-04-05', 'negative', -0.72, ARRAY['트러블발생', '안맞음', '실망'], '트러블/여드름', '트러블 및 화장품 부작용 불만족', '2026-04-05 08:24:30', 'e18f838f-e194-4453-8c34-4082d23eb25a');
